package com.levia.social.ui;

// Draft generated by FreeLLMAPI (Mistral-Small-3.2-24B); reviewed and corrected by Claude.

import android.content.Intent;
import android.os.Bundle;
import android.text.TextUtils;
import android.view.View;
import android.widget.TextView;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;

import com.google.android.material.textfield.TextInputEditText;
import com.levia.social.R;
import com.levia.social.data.model.ApiResponse;
import com.levia.social.data.model.ForgotPasswordRequest;
import com.levia.social.data.model.ResetPasswordRequest;
import com.levia.social.net.ApiClient;
import com.levia.social.net.ApiErrorParser;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;

/** Two-step password recovery: request a reset code by email, then enter the code and a new password. */
public class ForgotPasswordActivity extends AppCompatActivity {

    private TextInputEditText emailInput, codeInput, newPasswordInput;
    private TextView infoText, errorText;
    private View progress, step2Container, sendCodeButton, resetButton, backToLogin;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_forgot_password);

        emailInput = findViewById(R.id.emailInput);
        codeInput = findViewById(R.id.codeInput);
        newPasswordInput = findViewById(R.id.newPasswordInput);
        infoText = findViewById(R.id.infoText);
        errorText = findViewById(R.id.errorText);
        progress = findViewById(R.id.progress);
        step2Container = findViewById(R.id.step2Container);
        sendCodeButton = findViewById(R.id.sendCodeButton);
        resetButton = findViewById(R.id.resetButton);
        backToLogin = findViewById(R.id.backToLogin);

        sendCodeButton.setOnClickListener(new View.OnClickListener() {
            @Override public void onClick(View v) { requestCode(); }
        });
        resetButton.setOnClickListener(new View.OnClickListener() {
            @Override public void onClick(View v) { submitReset(); }
        });
        backToLogin.setOnClickListener(new View.OnClickListener() {
            @Override public void onClick(View v) { finish(); }
        });
    }

    private void requestCode() {
        String email = String.valueOf(emailInput.getText()).trim();
        if (TextUtils.isEmpty(email)) {
            showError(getString(R.string.fp_enter_email));
            return;
        }
        setLoading(true);
        ApiClient.get(this).forgotPassword(new ForgotPasswordRequest(email))
                .enqueue(new Callback<ApiResponse<Object>>() {
                    @Override
                    public void onResponse(Call<ApiResponse<Object>> call, Response<ApiResponse<Object>> r) {
                        setLoading(false);
                        if (r.isSuccessful() && r.body() != null && r.body().success) {
                            infoText.setText(R.string.fp_sent_note);
                            infoText.setVisibility(View.VISIBLE);
                            step2Container.setVisibility(View.VISIBLE);
                        } else {
                            showError(ApiErrorParser.message(r));
                        }
                    }

                    @Override
                    public void onFailure(Call<ApiResponse<Object>> call, Throwable t) {
                        setLoading(false);
                        showError(ApiErrorParser.networkMessage(t));
                    }
                });
    }

    private void submitReset() {
        String code = String.valueOf(codeInput.getText()).trim();
        // Passwords are NOT trimmed: spaces are part of the password.
        String newPassword = String.valueOf(newPasswordInput.getText());

        if (TextUtils.isEmpty(code)) {
            showError(getString(R.string.fp_enter_code));
            return;
        }
        if (!isStrongEnough(newPassword)) {
            showError(getString(R.string.fp_weak_password));
            return;
        }
        setLoading(true);
        ApiClient.get(this).resetPassword(new ResetPasswordRequest(code, newPassword))
                .enqueue(new Callback<ApiResponse<Object>>() {
                    @Override
                    public void onResponse(Call<ApiResponse<Object>> call, Response<ApiResponse<Object>> r) {
                        setLoading(false);
                        if (r.isSuccessful() && r.body() != null && r.body().success) {
                            Toast.makeText(ForgotPasswordActivity.this, R.string.fp_reset_done, Toast.LENGTH_LONG).show();
                            Intent i = new Intent(ForgotPasswordActivity.this, LoginActivity.class);
                            i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TASK);
                            startActivity(i);
                            finish();
                        } else {
                            showError(ApiErrorParser.message(r));
                        }
                    }

                    @Override
                    public void onFailure(Call<ApiResponse<Object>> call, Throwable t) {
                        setLoading(false);
                        showError(ApiErrorParser.networkMessage(t));
                    }
                });
    }

    /** Mirrors the server policy: 8-72 characters with at least one letter and one digit. */
    private static boolean isStrongEnough(String p) {
        if (p.length() < 8 || p.length() > 72) return false;
        boolean letter = false, digit = false;
        for (int i = 0; i < p.length(); i++) {
            char c = p.charAt(i);
            if (Character.isLetter(c)) letter = true;
            else if (Character.isDigit(c)) digit = true;
        }
        return letter && digit;
    }

    private void setLoading(boolean loading) {
        progress.setVisibility(loading ? View.VISIBLE : View.GONE);
        sendCodeButton.setEnabled(!loading);
        resetButton.setEnabled(!loading);
        if (loading) errorText.setVisibility(View.GONE);
    }

    private void showError(String msg) {
        errorText.setText(msg);
        errorText.setVisibility(View.VISIBLE);
    }
}
